?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laboratorium · <?=h(APP_NAME)?></title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="../assets/style.css"></head><body class="bg-body-tertiary"><nav class="navbar navbar-expand-lg bg-white border-bottom sticky-top"><div class="container py-2"><a class="navbar-brand fw-bold text-success" href="../index.php"><?=h(APP_NAME)?></a><div class="navbar-nav ms-auto"><a class="nav-link" href="../index.php">Dashboard</a><a class="nav-link active" href="index.php">LAB</a><a class="nav-link" href="../ijin/index.php">Ijin WA</a><a class="nav-link" href="../chat_dokter.php">Chat Dokter</a><a class="nav-link" href="../master.php">Master Data</a><a class="nav-link" href="../settings.php">Template</a><a class="nav-link" href="../report.php">Report</a></div></div></nav><main class="container py-4 py-lg-5"><div class="mb-4"><span class="badge text-bg-success-subtle text-success mb-2">LABORATORIUM</span><h1 class="h3 mb-1">Kirim Hasil Pemeriksaan Laboratorium</h1><p class="text-secondary">Pengiriman tetap memakai PDF hasil pemeriksaan dan caption.</p></div><div class="card shadow-sm border-0"><div class="card-body"><form id="f"><div class="row g-3"><div class="col-md-6"><label class="form-label">Nomor WhatsApp</label><input id="n" class="form-control" placeholder="0812..., pisahkan koma" required></div><div class="col-md-6"><label class="form-label">No. Registrasi</label><input id="r" maxlength="7" class="form-control" inputmode="numeric" required></div><div class="col-12"><label class="form-label">Caption</label><textarea id="m" class="form-control" rows="7" required></textarea></div></div><button class="btn btn-success mt-3" id="b">Kirim PDF WhatsApp</button></form><div id="o" class="mt-3"></div></div></div></main><script>document.getElementById('f').addEventListener('submit',async e=>{e.preventDefault();const b=document.getElementById('b'),o=document.getElementById('o');b.disabled=true;b.textContent='Mengirim...';try{const r=await fetch('../services/lab/api-send.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({numbers:document.getElementById('n').value,message:document.getElementById('r').value+document.getElementById('m').value})});const j=await r.json();o.innerHTML='<div class="alert '+(j.success?'alert-success':'alert-danger')+'">'+(j.message||JSON.stringify(j))+'</div>'}catch(x){o.innerHTML='<div class="alert alert-danger">'+x.message+'</div>'}finally{b.disabled=false;b.textContent='Kirim PDF WhatsApp'}});</script></body></html>